EVA Demo<div class="row sectionBlockLayout text-left" style="margin: 0px; min-height: auto; padding: 8px;">
  <div class="container" style="display: flex; flex-wrap: wrap;"><div class="col-md-12 columnBlockLayout" 
    style="flex-grow: 1; display: flex; flex-direction: column; min-width: 310px; word-break: break-word; padding: 
    16px; margin: 60px 0px;">

{% assign leadid = request.params["leadid"] %}
{% if leadid %}
  {% entityform name: 'Lead edit', recordid: leadid %}
{% else %}
  {% entityform name: 'Lead Insert' %}
{% endif %}
</div></div>
</div>EVA Demo
